insert into academy.entry_categories (entry_id,category_id,position) values ('tool-integration-fundamentals','09',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('tool-integration-fundamentals','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: מודל מציע reserve_item עם itemId ו־quantity. ASP.NET מאמת DTO, משתמש, מחסן וכמות מול SQL; לאחר אישור משתמש מבוצעת טרנזקציה עם מפתח מניעת כפילות. בקשה חוזרת אינה יוצרת הזמנה נוספת.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','אפשר לתרגל ב־C# עם Controller, DTO, HttpClient ושירות עסקי קטן. Microsoft.Extensions.AI מדגימה abstractions והפעלת כלים; אין צורך בשפת שרת נוספת או בהוספת framework כדי להבין הרשאה.','REST ישיר מספיק לעיתים לצרכן אחד; MCP מוסיף חוזה חוצה יישומים; connector מנוהל מוסיף אחריות ספק. יסודות סוכנים ב־02 ואבטחה ב־10 משלימים את הפרק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('tool-integration-fundamentals',0,'תפקיד וזרימת עבודה','Tool Calling מחזיר בקשה להפעלת פונקציה; היישום מחליט אם ואיך לבצע אותה. JSON Schema ו־OpenAPI מתארים קלט וחוזה, אך אינם ACL, טרנזקציה או idempotency. REST, connector ו־MCP הם דרכי חיבור שונות לאותה יכולת עסקית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('tool-integration-fundamentals',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי: קראו לפני MCP או מוצר connectors. מתחילים בכלי קריאה אחד; פעולת כתיבה מצטרפת רק עם אישור מפורש ובקרות עסקיות. אפשר לתרגל ב־C# עם Controller, DTO, HttpClient ושירות עסקי קטן. Microsoft.Extensions.AI מדגימה abstractions והפעלת כלים; אין צורך בשפת שרת נוספת או בהוספת framework כדי להבין הרשאה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('tool-integration-fundamentals',2,'יתרונות ומתי לבחור','פרק שאינו תלוי בספק מאפשר למחזר לוגיקה עסקית קיימת ולהפריד אותה מהמודל. אפשר לבדוק הרשאה וחוזה גם בלי LLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('tool-integration-fundamentals',3,'חסרונות, אבטחה ורישוי','תכנון נכון דורש בדיקות כפילויות, retries ו־tenant isolation. אין לייצר אוטומטית כלי כתיבה לכל endpoint; רישיון שירות או SDK נבדק בנפרד מהמפרט. תמיכת importer ב־OpenAPI3.2.1 אינה נובעת מקיום המפרט.');
insert into academy.entry_sections (entry_id,position,title,body) values ('tool-integration-fundamentals',4,'השוואה לחלופות','REST ישיר מספיק לעיתים לצרכן אחד; MCP מוסיף חוזה חוצה יישומים; connector מנוהל מוסיף אחריות ספק. יסודות סוכנים ב־02 ואבטחה ב־10 משלימים את הפרק.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('tool-integration-fundamentals','must_learn','ידע חובה לכל מפתח: בקשת מודל אינה הרשאה, וחוזה תקין אינו הוכחת נכונות עסקית.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('tool-integration-fundamentals','יסודות חוזי כלים, OpenAPI והרשאות: הפרדה בין הצעת מודל, אימות קלט וביצוע פעולה עסקית.','אפשר לתרגל ב־C# עם Controller, DTO, HttpClient ושירות עסקי קטן. Microsoft.Extensions.AI מדגימה abstractions והפעלת כלים; אין צורך בשפת שרת נוספת או בהוספת framework כדי להבין הרשאה.','not_applicable','פרק מושגי ללא מאגר מוצר מייצג.','2026-11-03');
