insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('mcp-csharp-sdk','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: שרת ASP.NET חושף get_stock מעל שירות מחסן עם DI ו־cancellation. לקוח .NET מגלה כלי, קורא לו ובודק קלט חסר והרשאה חסרה; אחר כך נבדק אותו שרת ב־Inspector.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','זהו SDK C# רשמי, ולא רק יכולת לצרוך HTTP. אין להניח שוויון תכונות עם Python/TypeScript. תג v2.3.1 מ־03/11/2026 כולל תיקון authenticated stateful sessions; זמינות חבילות NuGet המדויקות לא אומתה ולכן יש לבדוק לפני התקנה.','FastMCP הוא חלופת Python, ו־REST ישיר מתאים כשאין צורך בפרוטוקול MCP. Inspector הוא כלי בדיקה משלים, לא SDK חלופי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-csharp-sdk',0,'תפקיד וזרימת עבודה','הפרויקט הרשמי של modelcontextprotocol, בשיתוף Microsoft, מספק APIs ללקוח ולשרת. Core, חבילת hosting/DI ו־AspNetCore ממלאות תפקידים שונים. בוחרים transport וגרסת פרוטוקול לפני כתיבת wrapper מעל השירות העסקי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-csharp-sdk',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי למפתח .NET: ספרייה אחת מספיקה לתרגיל ראשון. אין צורך לתרגל במקביל FastMCP. זהו SDK C# רשמי, ולא רק יכולת לצרוך HTTP. אין להניח שוויון תכונות עם Python/TypeScript. תג v2.3.1 מ־03/11/2026 כולל תיקון authenticated stateful sessions; זמינות חבילות NuGet המדויקות לא אומתה ולכן יש לבדוק לפני התקנה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-csharp-sdk',2,'יתרונות ומתי לבחור','שימוש במושגי .NET קיימים מקטין מעבר בין שפות ומאפשר בדיקות חוזה ללא מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-csharp-sdk',3,'חסרונות, אבטחה ורישוי','SDK אינו מעניק הרשאה עסקית או בידוד. רישוי במעבר: תרומות חדשות Apache2, תרומות MIT ישנות שלא הוחלפו ותיעוד שאינו מפרט CC-BY4; יש לקרוא LICENSE/NOTICE לגרסה שנבחרה. תיקון אבטחה אינו הבטחת בטיחות של כל שרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-csharp-sdk',4,'השוואה לחלופות','FastMCP הוא חלופת Python, ו־REST ישיר מתאים כשאין צורך בפרוטוקול MCP. Inspector הוא כלי בדיקה משלים, לא SDK חלופי.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('mcp-csharp-sdk','should_know','כדאי להכיר כמסלול מימוש טבעי ל־.NET אחרי הבנת הפרוטוקול וההרשאות.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('mcp-csharp-sdk','SDK רשמי למימוש לקוחות ושרתי MCP ב־.NET, עם חבילות Core, hosting ו־ASP.NET Core.','זהו SDK C# רשמי, ולא רק יכולת לצרוך HTTP. אין להניח שוויון תכונות עם Python/TypeScript. תג v2.3.1 מ־03/11/2026 כולל תיקון authenticated stateful sessions; זמינות חבילות NuGet המדויקות לא אומתה ולכן יש לבדוק לפני התקנה.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
