insert into academy.entry_categories (entry_id,category_id,position) values ('mcp-inspector','09',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('mcp-inspector','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: בדקו tools/list ו־tools/call מול שרת המחסן ב־C#, עם כמות חסרה, שם כלי שגוי וזהות ללא הרשאה. תכננו artifact תוצאה ל־CI בלי לשמור טוקנים בלוג.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','סביבת הכלי Node/JS/TS; הוא בודק שרת C# באמצעות MCP ואינו ספריית .NET. יש להצמיד runtime וגרסת כלי; דרישת engines מינימלית אינה הוכחת עדכניות אבטחה.','אפשר להתחיל בבדיקות SDK ידניות; Inspector מקל על חקירת פרוטוקול. Promptfoo ב־10 בודק התנהגות יישום ותשובות, ולכן הוא משלים ולא אותו כלי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-inspector',0,'תפקיד וזרימת עבודה','Inspector מספק מסלולי Web, CLI ו־TUI לבדיקת שרת. בקו v2 כלי mcpdo מסומן Experimental; קו v1 מקבל תיקוני אבטחה בלבד. בחירת CLI ואופן האימות צריכים להתאים לקו הגרסה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-inspector',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי: אחרי שרת read-only ראשון, בדקו את החוזה לפני חיבור מודל. סביבת הכלי Node/JS/TS; הוא בודק שרת C# באמצעות MCP ואינו ספריית .NET. יש להצמיד runtime וגרסת כלי; דרישת engines מינימלית אינה הוכחת עדכניות אבטחה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-inspector',2,'יתרונות ומתי לבחור','בדיקה דטרמיניסטית מספקת בידוד תקלה לפני הרצת סוכן והוצאות מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-inspector',3,'חסרונות, אבטחה ורישוי','אינו sandbox להרצת כל שרת ואינו eval לאיכות תשובה או כיסוי אבטחה. טוקנים ותוכן שרת דורשים טיפול. רישוי MCP במעבר Apache2/MIT ותיעוד CC-BY4 לפי LICENSE; אין רישיון יחיד גורף לכל ההיסטוריה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp-inspector',4,'השוואה לחלופות','אפשר להתחיל בבדיקות SDK ידניות; Inspector מקל על חקירת פרוטוקול. Promptfoo ב־10 בודק התנהגות יישום ותשובות, ולכן הוא משלים ולא אותו כלי.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('mcp-inspector','should_know','כדאי להכיר כדי להפריד כשל שרת או פרוטוקול מטעות בחירת כלי של המודל.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('mcp-inspector','כלי פיתוח לבדיקת שרתי MCP, גילוי כלים, חוזים ושגיאות בלי תלות בהתנהגות מודל.','סביבת הכלי Node/JS/TS; הוא בודק שרת C# באמצעות MCP ואינו ספריית .NET. יש להצמיד runtime וגרסת כלי; דרישת engines מינימלית אינה הוכחת עדכניות אבטחה.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
