insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('fastmcp','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: הפיקו אבטיפוס ממפרט OpenAPI של מחסן, ואז צמצמו ידנית לשני כלים עסקיים לקריאה בלבד. חברו לקוח C# ובדקו שהרשאות API נשמרות.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','הליבה ו־API ב־Python; לקוח .NET צורך שרת תואם MCP. לא אומת SDK C# מקומי של FastMCP.','לשירות ASP.NET קיים עדיף להתחיל ב־MCP C# SDK; Python SDK הרשמי הוא מסלול נוסף. אין צורך לתרגל את שלושתם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('fastmcp',0,'תפקיד וזרימת עבודה','FastMCP של PrefectHQ היא זהות אחת גם כשהפניה ישנה משתמשת jlowin/fastmcp. היא מובחנת מהמימוש שהוטמע ב־Python SDK הרשמי. גישור OpenAPI הוא נקודת פתיחה, לא החלטה לחשוף את כל ה־API למודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('fastmcp',1,'מסלול לימוד ושילוב ב־C#/.NET','השוואה והתמחות Python: אינה שלב נוסף שחובה לתרגל במסלול C#. הליבה ו־API ב־Python; לקוח .NET צורך שרת תואם MCP. לא אומת SDK C# מקומי של FastMCP.');
insert into academy.entry_sections (entry_id,position,title,body) values ('fastmcp',2,'יתרונות ומתי לבחור','הגדרת כלים תמציתית וגשר OpenAPI עשויים להאיץ אבטיפוס כש־Python כבר במערכת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('fastmcp',3,'חסרונות, אבטחה ורישוי','חשיפה אוטומטית של REST רחב עשויה ליצור כלים מבלבלים או רגישים. Apache2 של הספרייה אינו רישיון השירות שמאחוריה; טענות הספק על ביצועים אינן benchmark שבוצע כאן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('fastmcp',4,'השוואה לחלופות','לשירות ASP.NET קיים עדיף להתחיל ב־MCP C# SDK; Python SDK הרשמי הוא מסלול נוסף. אין צורך לתרגל את שלושתם.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('fastmcp','should_know','כדאי להכיר כחלופת Python וגשר לאינטגרציות, בלי לחייב מעבר שפה.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('fastmcp','מסגרת Python לבניית שרתי ולקוחות MCP, עם אפשרות לגישור מפרטי OpenAPI.','הליבה ו־API ב־Python; לקוח .NET צורך שרת תואם MCP. לא אומת SDK C# מקומי של FastMCP.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
