insert into academy.entry_categories (entry_id,category_id,position) values ('github-mcp-server','09',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('github-mcp-server','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: סכמו issues ו־PRs פתוחים במאגר בדיקה באמצעות toolsets מצומצמים. בדקו שהזהות אינה יכולה לפרסם תגובה, לבצע merge או לקרוא מאגר שאינו מורשה.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','המימוש ב־Go; שילוב C# הוא דרך לקוח MCP תואם, לא SDK .NET של השרת.','GitHub REST או CLI ישירים עשויים להספיק לצרכן יחיד. זהו תרגיל אינטגרציה ולא תחליף ל־framework סוכנים ב־02.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-mcp-server',0,'תפקיד וזרימת עבודה','השרת הרשמי נפרד מ־Copilot ומשרת GitHub reference המאורכב. מסלולי local/remote אינם זהים בכל יכולת; יש לבחור כלים ו־scopes מפורשים ולא להפעיל כל הרשאה שמוצעת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-mcp-server',1,'מסלול לימוד ושילוב ב־C#/.NET','תרגול מרכזי אחרי Inspector: אינטגרציה אמיתית בקריאה בלבד, על מאגר שמותר לגשת אליו. המימוש ב־Go; שילוב C# הוא דרך לקוח MCP תואם, לא SDK .NET של השרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-mcp-server',2,'יתרונות ומתי לבחור','אינטגרציה רשמית מדגימה discovery, הרשאות והפרדה בין קריאה לכתיבה ב־workflow מוכר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-mcp-server',3,'חסרונות, אבטחה ורישוי','תוכן issues אינו מהימן ועלול להשפיע על המודל. read-only מסנן כלי כתיבה; lockdown הוא best-effort ואינו security boundary. קוד MIT נפרד מתנאי שירות GitHub ומהרשאות החשבון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-mcp-server',4,'השוואה לחלופות','GitHub REST או CLI ישירים עשויים להספיק לצרכן יחיד. זהו תרגיל אינטגרציה ולא תחליף ל־framework סוכנים ב־02.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('github-mcp-server','should_know','כדאי להכיר משום שהוא מדגים גבול הרשאות ואינטגרציה שימושית למפתח בלי לבנות connector מהתחלה.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('github-mcp-server','שרת GitHub רשמי החושף פעולות מאגר דרך MCP, עם בחירת toolsets ומצב קריאה בלבד.','המימוש ב־Go; שילוב C# הוא דרך לקוח MCP תואם, לא SDK .NET של השרת.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
