insert into academy.entry_categories (entry_id,category_id,position) values ('playwright-mcp','09',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('playwright-mcp','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: ביישום React מבודד בדקו workflow RTL, זיהוי שדה חסר וצילום תוצאה. השתמשו בחשבון בדיקה, בלי פעולות production או שליחת מידע אמיתי.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','שרת Node/TypeScript נצרך מלקוח MCP תואם, לרבות C#. אפשרות codegen=csharp אינה הופכת את שרת MCP ל־SDK .NET מקומי.','Playwright test/CLI מתאים לעיתים יותר ל־E2E דטרמיניסטי; GitHub MCP מדגים כלי API. אין צורך להמיר כל בדיקת UI לפעולת מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('playwright-mcp',0,'תפקיד וזרימת עבודה','שרת Microsoft חושף כלי דפדפן לסוכן. הוא שונה מ־Playwright testing API וממסלול CLI+Skills. בחירת UI automation מוצדקת כשהמשימה תלויה בממשק; בדיקה חוזרת ידועה יכולה להישאר דטרמיניסטית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('playwright-mcp',1,'מסלול לימוד ושילוב ב־C#/.NET','התמחות UI ובדיקות React: אין חובה להוסיף דפדפן לתרגיל API בסיסי. שרת Node/TypeScript נצרך מלקוח MCP תואם, לרבות C#. אפשרות codegen=csharp אינה הופכת את שרת MCP ל־SDK .NET מקומי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('playwright-mcp',2,'יתרונות ומתי לבחור','שימוש ב־accessibility snapshots מאפשר לתאר פעולות בממשק כשאין API מתאים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('playwright-mcp',3,'חסרונות, אבטחה ורישוי','דפים, cookies ופעולות UI מגדילים את גבול האמון. אפשרויות origins אינן security boundary. Apache2 לקוד; תג0.0.x non-prerelease אינו הבטחת יציבות API או בידוד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('playwright-mcp',4,'השוואה לחלופות','Playwright test/CLI מתאים לעיתים יותר ל־E2E דטרמיניסטי; GitHub MCP מדגים כלי API. אין צורך להמיר כל בדיקת UI לפעולת מודל.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('playwright-mcp','should_know','כדאי להכיר כגשר לפעולות UI, לאחר הבנת גבולות הרשאות ותוכן לא מהימן.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('playwright-mcp','שרת לאוטומציית דפדפן דרך snapshots נגישות, כשנדרשת פעולה בממשק ולא רק קריאת API.','שרת Node/TypeScript נצרך מלקוח MCP תואם, לרבות C#. אפשרות codegen=csharp אינה הופכת את שרת MCP ל־SDK .NET מקומי.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
