insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('composio','HTTP/JSON, DTO והרשאות; קראו יסודות כלים לפני חיבור כלי עסקי.','דוגמה מעשית מוצעת שלא הורצה: שירות מסכם ללקוח issues מחשבון GitHub המחובר שלו בלבד. בדקו בידוד שני משתמשים, ביטול חיבור ו־scopes לקריאה; כתיבה דורשת אישור נפרד.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','מסלולים מאומתים: SDKs Python/TypeScript ו־MCP/HTTP. SDK C# מקומי רשמי לא אומת; שירות .NET יכול לצרוך ממשק נתמך לאחר בדיקת החוזה.','שרת MCP רשמי של הספק, HttpClient או workflow ב־n8n עשויים להספיק. אין כפילות עם n8n: כאן הדגש על חיבורים וזהויות, לא תזמור כל התהליך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('composio',0,'תפקיד וזרימת עבודה','Composio מנהלת חיבורים ו־sessions לכלים אצל ספקים חיצוניים. יש להפריד זהות משתמש, scopes, חשבון מחובר ובחירת כלי; ריבוי connectors אינו צורך בסיסי של כל יישום.');
insert into academy.entry_sections (entry_id,position,title,body) values ('composio',1,'מסלול לימוד ושילוב ב־C#/.NET','העשרה והשוואה: רק אחרי OAuth ואחריות השירות; אין צורך לתרגל כשחיבור ישיר אחד מספיק. מסלולים מאומתים: SDKs Python/TypeScript ו־MCP/HTTP. SDK C# מקומי רשמי לא אומת; שירות .NET יכול לצרוך ממשק נתמך לאחר בדיקת החוזה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('composio',2,'יתרונות ומתי לבחור','ניהול OAuth ו־refresh מרוכז יכול להפחית קוד אינטגרציה עבור שירותים רבים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('composio',3,'חסרונות, אבטחה ורישוי','טוקנים אצל צד נוסף, עלות ותלות ספק מחייבים תכנון. MIT של SDK monorepo אינו רישיון לכל backend או היתר self-host; מחיר, SLA ואזורי אחסון לא אומתו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('composio',4,'השוואה לחלופות','שרת MCP רשמי של הספק, HttpClient או workflow ב־n8n עשויים להספיק. אין כפילות עם n8n: כאן הדגש על חיבורים וזהויות, לא תזמור כל התהליך.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('composio','enrichment','העשרה לניהול חיבורים מרובים; תלות SaaS וחפיפה לאינטגרציה ישירה אינן מצדיקות חובת מוצר.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('composio','שירות חיבורים וכלים מנוהלים, עם OAuth וחיבורים לפי משתמש עבור אינטגרציות לסוכנים.','מסלולים מאומתים: SDKs Python/TypeScript ו־MCP/HTTP. SDK C# מקומי רשמי לא אומת; שירות .NET יכול לצרוך ממשק נתמך לאחר בדיקת החוזה.','verified','מאגר SDKs/CLI של Composio בלבד; אינו קוד כל שירות ה־SaaS ואינו מדד משתמשיו.','2026-11-03');
