insert into academy.entry_categories (entry_id,category_id,position) values ('ai-quality-security-fundamentals','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('ai-quality-security-fundamentals','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: הגדירו20 בקשות ציוד, כולל בקשה עמומה, מקור שגוי והוראות זדוניות במסמך. לכל אחת הגדירו expected outcome והרשאות; בדקו שאף ציון שופט אינו מאפשר כתיבת SQL ללא אישור.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','אפשר להתחיל ב־xUnit, לוגים מובנים ו־ActivitySource ב־C#. כלי Python, פלטפורמת traces ו־LLM judge הם בחירות המשך, לא דרישות קדם לכל תרגיל.','התחילו בבדיקות רגילות ולוגים; OTel משמש instrumentation, Langfuse/LangSmith/Phoenix חקירת ריצה, Microsoft Evaluation/Promptfoo/Ragas הערכה, ו־NeMo policy. אלה שכבות משלימות ולא כלים שחייבים לתרגל כולם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-quality-security-fundamentals',0,'תפקיד וזרימת עבודה','Trace ו־span מסבירים מה התרחש בריצה; dataset ו־regression בוחנים שינוי על אוסף דוגמאות. assertions דטרמיניסטיות ו־LLM-as-judge עונים על שאלות שונות. Threat model, prompt injection והרשאות עסקיות שייכים לתכנון מראש ולא רק למסנן פלט בסוף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-quality-security-fundamentals',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי וחובה: התחילו ב־dataset קטן, הרשאות ונתונים אסורים לפליטה לפני בחירת מוצר. אפשר להתחיל ב־xUnit, לוגים מובנים ו־ActivitySource ב־C#. כלי Python, פלטפורמת traces ו־LLM judge הם בחירות המשך, לא דרישות קדם לכל תרגיל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-quality-security-fundamentals',2,'יתרונות ומתי לבחור','יסודות משותפים מאפשרים להשוות כלים באותו תרחיש ולהפוך תקלה לדוגמת regression במקום להחליף מוצר בעקבות הדגמה אחת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-quality-security-fundamentals',3,'חסרונות, אבטחה ורישוי','score של שופט אינו אמת קרקע ואוסף בדיקות אינו הוכחת בטיחות. יש לכייל מול אדם, להגן על prompts ונתוני trace ולהבחין בעלויות. מקור OWASP הוא מהדורת2026; יום פרסום מדויק שנוי במקורות ולכן אינו מוצג.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-quality-security-fundamentals',4,'השוואה לחלופות','התחילו בבדיקות רגילות ולוגים; OTel משמש instrumentation, Langfuse/LangSmith/Phoenix חקירת ריצה, Microsoft Evaluation/Promptfoo/Ragas הערכה, ו־NeMo policy. אלה שכבות משלימות ולא כלים שחייבים לתרגל כולם.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('ai-quality-security-fundamentals','must_learn','ידע חובה: איכות, תצפיתיות והרשאה הם ממדים נפרדים. אין מוצר יחיד שחובה להשתמש בו כדי ללמוד אותם.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('ai-quality-security-fundamentals','יסודות tracing, הערכה שיטתית ואבטחת AI: להבחין בין חקירת ריצה, נכונות תשובה והרשאת פעולה.','אפשר להתחיל ב־xUnit, לוגים מובנים ו־ActivitySource ב־C#. כלי Python, פלטפורמת traces ו־LLM judge הם בחירות המשך, לא דרישות קדם לכל תרגיל.','not_applicable','פרק מושגי ללא מאגר מוצר מייצג.','2026-11-03');
