insert into academy.entry_categories (entry_id,category_id,position) values ('opentelemetry','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('opentelemetry','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: שירות ASP.NET יוצר Activity סביב retrieval, HTTP model call ו־SQL; תכננו redaction לפני export וודאו שקישור spans נשמר ביעד שנבחר בלי להקליט מסמכים מלאים.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','SDK .NET רשמי מאפשר instrumentation ב־C#. GenAI semantic conventions הועברו למאגר ייעודי, וחלק מהערכים Development או deprecated; יציבות SDK core אינה יציבות של כל attribute או mapping ליעד.','Langfuse, LangSmith ו־Phoenix הם יעדים אפשריים בתנאי שילוב מתאימים; Microsoft Evaluation היא ספריית בדיקות משלימה ולא backend של traces.');
insert into academy.entry_sections (entry_id,position,title,body) values ('opentelemetry',0,'תפקיד וזרימת עבודה','ב־.NET יוצרים ActivitySource/Activity סביב פעולות ומייצאים telemetry. OTLP הוא מסלול העברה ל־backend ואינו מאגר traces. זהות trace וקשר parent/child מחברים בקשות REST, מודל ואחזור בלי להעביר לוגיקה עסקית לפלטפורמה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('opentelemetry',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי ב־.NET: exporter אחד ו־backend אחד תחילה; אין חובה ללמוד כל פלטפורמת traces. SDK .NET רשמי מאפשר instrumentation ב־C#. GenAI semantic conventions הועברו למאגר ייעודי, וחלק מהערכים Development או deprecated; יציבות SDK core אינה יציבות של כל attribute או mapping ליעד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('opentelemetry',2,'יתרונות ומתי לבחור','תקן instrumentation מצמצם תלות ב־SDK של backend ומשתלב בידע tracing של מערכות REST.');
insert into academy.entry_sections (entry_id,position,title,body) values ('opentelemetry',3,'חסרונות, אבטחה ורישוי','מיפוי GenAI ותמיכת יעד דורשים בדיקה לפי גרסה. capture של prompts עלול לחשוף מידע; sampling ונפח אחסון משנים עלות. SDK .NET ברישיון Apache2, אך רישיון ותנאי backend נפרדים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('opentelemetry',4,'השוואה לחלופות','Langfuse, LangSmith ו־Phoenix הם יעדים אפשריים בתנאי שילוב מתאימים; Microsoft Evaluation היא ספריית בדיקות משלימה ולא backend של traces.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('opentelemetry','should_know','כדאי להכיר בעדיפות מעשית גבוהה: instrumentation נייד מחבר ידע ניטור רגיל ליישומי AI.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('opentelemetry','APIs ו־SDK .NET ליצירת traces והעברתם באמצעות OTLP ליעד תצפיתיות, עם מיפוי GenAI תלוי גרסה.','SDK .NET רשמי מאפשר instrumentation ב־C#. GenAI semantic conventions הועברו למאגר ייעודי, וחלק מהערכים Development או deprecated; יציבות SDK core אינה יציבות של כל attribute או mapping ליעד.','verified','מאגר SDK .NET בלבד, ללא contrib או GenAI conventions; אין ייחוס Stars לכל OpenTelemetry או למערכת תצפיתיות.','2026-11-03');
