insert into academy.entry_categories (entry_id,category_id,position) values ('microsoft-ai-evaluation','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-ai-evaluation','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: xUnit בודק DTO, הפניה למקור והימנעות מכתיבה; הוסיפו Groundedness או Relevance ל־dataset מסומן ידנית ותעדו גרסת prompt, מודל שופט, cache ועלות.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','ספריות C#/.NET עם שילוב xUnit/MSTest/NUnit ו־CI. NuGet10.11.0 נצפתה ללא suffix Preview, אך RTC evaluator מסומן Experimental. אין להסיק שכל מעריך יציב, מקומי או ללא תלות שירות ענן.','Promptfoo מתאים לבדיקות HTTP/CI חיצוניות; Ragas להעמקת RAG בתהליך Python. בחרו runner אחד לתרגיל ראשון, לא שלוש מסגרות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-ai-evaluation',0,'תפקיד וזרימת עבודה','Evaluation מגדירה abstractions; NLP משווה טקסט בלי LLM, Quality משתמשת בשופט LLM ו־Safety משתמשת Microsoft Foundry Evaluation service. Reporting ו־Console מספקות שמירה ודוחות; Reporting.Azure היא אפשרות ולא חובת Azure לכל הערכה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-ai-evaluation',1,'מסלול לימוד ושילוב ב־C#/.NET','מסלול מרכזי מועדף למפתח C#: בדיקות דטרמיניסטיות קודם, ואז מעריך אחד שמכויל מול דוגמאות אנושיות. ספריות C#/.NET עם שילוב xUnit/MSTest/NUnit ו־CI. NuGet10.11.0 נצפתה ללא suffix Preview, אך RTC evaluator מסומן Experimental. אין להסיק שכל מעריך יציב, מקומי או ללא תלות שירות ענן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-ai-evaluation',2,'יתרונות ומתי לבחור','ממחזרת תשתית בדיקות ושפת פיתוח קיימות וניתן להפריד הערכה דטרמיניסטית מהערכה מבוססת מודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-ai-evaluation',3,'חסרונות, אבטחה ורישוי','Safety עשויה להעביר נתונים לשירות Foundry; Quality כרוכה בעלות ושונות שופט. MIT של חבילות אינו תנאי שירות ענן. מאגר dotnet/extensions רחב אינו מדד אימוץ לחבילה זו ולכן אין לו Stars משויכים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-ai-evaluation',4,'השוואה לחלופות','Promptfoo מתאים לבדיקות HTTP/CI חיצוניות; Ragas להעמקת RAG בתהליך Python. בחרו runner אחד לתרגיל ראשון, לא שלוש מסגרות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('microsoft-ai-evaluation','should_know','כדאי להכיר כמסלול הערכה טבעי באותה סביבת בדיקות .NET, בלי להידרש לשרת Python.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-ai-evaluation','משפחת ספריות .NET להערכת איכות ותוצאות AI ושילובן בבדיקות, דוחות ו־CI; דרישות הרצה שונות לכל מעריך.','ספריות C#/.NET עם שילוב xUnit/MSTest/NUnit ו־CI. NuGet10.11.0 נצפתה ללא suffix Preview, אך RTC evaluator מסומן Experimental. אין להסיק שכל מעריך יציב, מקומי או ללא תלות שירות ענן.','not_applicable','אין מאגר מוצר ציבורי יחיד מייצג; אין שיוך Stars של SDK או monorepo רחב לשירות או לחבילה.','2026-11-03');
