insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('promptfoo','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: CI פונה ל־endpoint בדיקות של ASP.NET עם fixtures סינתטיים, בוחן JSON, עקיפת tenant ופרמטרי כלי. הפעילו redteam רק מול יעד מורשה ומבודד.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','סביבת Node/TypeScript; .NET נבדקת דרך HTTP ולא SDK C# מקומי. providers ושופטים עשויים להוסיף נתיבי תעבורה ועלות.','Microsoft Evaluation מתאימה לבדיקות בתוך .NET; Ragas מתמקדת גם במדדי retrieval. Inspector ב־09 בודק פרוטוקול MCP ולא איכות תשובה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('promptfoo',0,'תפקיד וזרימת עבודה','Runner שולח מקרי בדיקה ליעד, מפעיל assertions ומשווה גרסאות. Red teaming מרחיב ניסיונות כשל אך אינו תחליף לבדיקת הרשאות דטרמיניסטית. יש להגדיר מהו כשל לפני השוואת ציון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('promptfoo',1,'מסלול לימוד ושילוב ב־C#/.NET','ליבה לבדיקות חיצוניות ו־CI לאחר בסיס בדיקות; אין חובה להוסיף כשבדיקות .NET פשוטות כבר מכסות את הצורך. סביבת Node/TypeScript; .NET נבדקת דרך HTTP ולא SDK C# מקומי. providers ושופטים עשויים להוסיף נתיבי תעבורה ועלות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('promptfoo',2,'יתרונות ומתי לבחור','בדיקות black-box מאפשרות להשוות שינויים לאורך זמן ולבדוק שירות .NET בלי העברת השרת ל־Python.');
insert into academy.entry_sections (entry_id,position,title,body) values ('promptfoo',3,'חסרונות, אבטחה ורישוי','Local-first אינו no-network: usage telemetry מופעל כברירת מחדל וקיימת בדיקת עדכונים; מודלים ושופטים יכולים לפנות לענן. הגדרת הספק על אי־שליחת prompts ב־telemetry אינה הבטחה לכל תעבורת המוצר. רישיון core MIT נפרד משירותים בתשלום.');
insert into academy.entry_sections (entry_id,position,title,body) values ('promptfoo',4,'השוואה לחלופות','Microsoft Evaluation מתאימה לבדיקות בתוך .NET; Ragas מתמקדת גם במדדי retrieval. Inspector ב־09 בודק פרוטוקול MCP ולא איכות תשובה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('promptfoo','should_know','כדאי להכיר לבדיקת חוזה יישום מבחוץ בלי להחליף stack עסקי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('promptfoo','כלי CLI וספרייה לבדיקות regression, assertions ו־red teaming מול מודלים ויישומים, לרבות יעד HTTP של .NET.','סביבת Node/TypeScript; .NET נבדקת דרך HTTP ולא SDK C# מקומי. providers ושופטים עשויים להוסיף נתיבי תעבורה ועלות.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
