insert into academy.entry_categories (entry_id,category_id,position) values ('ragas','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('ragas','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: השוו שני chunking/retrieval setups מאותם נוהלי רכש ובאותו אוסף שאלות; בדקו relevance ונאמנות למקור בנפרד והצליבו מדגם ידני.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','מסגרת Python; .NET יכולה לייצא dataset ותוצאות לתהליך הערכה נפרד. binding C# רשמי לא אומת ואין צורך לכתוב מחדש את השירות העסקי.','Microsoft Evaluation היא מסלול C# ראשון; Promptfoo לבדיקות יישום חיצוניות. DeepEval חלופה למחקר עתידי ולא תוספת מאושרת בסבב זה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragas',0,'תפקיד וזרימת עבודה','מכינים dataset ותוצאות מערכת, בוחרים מדדי retrieval או faithfulness ומכיילים אותם מול דוגמאות שנבדקו ידנית. כלי הערכה אינו runtime RAG חדש; הוא מסייע לאתר באיזו שכבה שינוי פוגע.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragas',1,'מסלול לימוד ושילוב ב־C#/.NET','התמחות הערכת RAG אחרי הבסיס; משלימה את קטגוריה04 ואינה תנאי לתרגיל .NET ראשון. מסגרת Python; .NET יכולה לייצא dataset ותוצאות לתהליך הערכה נפרד. binding C# רשמי לא אומת ואין צורך לכתוב מחדש את השירות העסקי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragas',2,'יתרונות ומתי לבחור','מדדים מובחנים תומכים בבחינת שינוי באחזור במקום להסתפק בציון תשובה כולל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragas',3,'חסרונות, אבטחה ורישוי','שופטי LLM מוסיפים עלות והטיה; dataset לא מייצג מייצר ביטחון שגוי. רישיון Apache2; ספקי השופטים נפרדים. head ו־release שנמדדו ישנים יותר מחלק מהכלים האחרים, אך אין בכך ראיה ל־Maintenance או נטישה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ragas',4,'השוואה לחלופות','Microsoft Evaluation היא מסלול C# ראשון; Promptfoo לבדיקות יישום חיצוניות. DeepEval חלופה למחקר עתידי ולא תוספת מאושרת בסבב זה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('ragas','should_know','כדאי להכיר להפרדת כשל retrieval מכשל תשובה, כשמדדי RAG ותהליך Python מצדיקים זאת.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('ragas','מסגרת הערכה ל־RAG, workflows וסוכנים, עם מדדים שמפרידים אחזור, נאמנות למקור והתנהגות כלי.','מסגרת Python; .NET יכולה לייצא dataset ותוצאות לתהליך הערכה נפרד. binding C# רשמי לא אומת ואין צורך לכתוב מחדש את השירות העסקי.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
