insert into academy.entry_categories (entry_id,category_id,position) values ('langsmith','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('langsmith','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: השתמשו באותו dataset של תרחיש מלאי בניסוי נפרד, הוסיפו הערכה אנושית וקוד לפני online judge, והשוו יכולת לחקור כשל בלי להמציא benchmark.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','ל־.NET מסלול OpenTelemetry; SDK C# ייעודי עם parity מלא לא אומת. היקף auto-instrumentation וניהול datasets תלוי בנתיב השילוב.','Langfuse כבר בקטלוג ויכולה להספיק; Phoenix מציעה workflow אחר ורישוי ELv2. OTel הוא instrumentation משלים ולא פלטפורמה מתחרה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langsmith',0,'תפקיד וזרימת עבודה','LangSmith מרכזת traces ו־datasets ומפעילה הערכות offline/online באמצעות אדם, קוד או שופט LLM. היא מוצר נפרד מ־LangChain ומ־LangGraph; SDK framework אינו רישיון הפלטפורמה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langsmith',1,'מסלול לימוד ושילוב ב־C#/.NET','השוואה והתמחות: בחרו Langfuse או LangSmith או Phoenix למעבדה, ולא שלושה backends. ל־.NET מסלול OpenTelemetry; SDK C# ייעודי עם parity מלא לא אומת. היקף auto-instrumentation וניהול datasets תלוי בנתיב השילוב.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langsmith',2,'יתרונות ומתי לבחור','שילוב tracing והערכה מאפשר לחבר כשל ריצה לניסוי שיטתי, ומתאים להשוואת workflow מוכר באקוסיסטם LangChain.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langsmith',3,'חסרונות, אבטחה ורישוי','SaaS/Hybrid/self-host תלויים במסלול מסחרי; self-host/BYOC דורש Enterprise לפי המקור. אין לייחס Stars של SDK או MIT של LangChain לכל השירות. יש לבחון מידע, גישה ועלות שופטים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langsmith',4,'השוואה לחלופות','Langfuse כבר בקטלוג ויכולה להספיק; Phoenix מציעה workflow אחר ורישוי ELv2. OTel הוא instrumentation משלים ולא פלטפורמה מתחרה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('langsmith','should_know','כדאי להכיר כחלופה משמעותית, במיוחד לצד LangChain/LangGraph שכבר נלמדות, ללא חובת שימוש.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('langsmith','פלטפורמת tracing, datasets וניסויי הערכה כחלופה ל־Langfuse, לרבות מערכות שאינן משתמשות ב־LangChain.','ל־.NET מסלול OpenTelemetry; SDK C# ייעודי עם parity מלא לא אומת. היקף auto-instrumentation וניהול datasets תלוי בנתיב השילוב.','not_applicable','אין מאגר מוצר ציבורי יחיד מייצג; אין שיוך Stars של SDK או monorepo רחב לשירות או לחבילה.','2026-11-03');
