insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('arize-phoenix','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: חקרו trace של תשובה עם ציטוט שגוי והפכו אותו לניסוי על שני retrievers; תעדו האם הבעיה נובעת מהמסמך, האחזור או המודל.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','לקוחות Python/TypeScript; .NET דרך OTLP ו־manual spans. אין הבטחת auto-instrumentation או שוויון יכולות eval לכל שפה.','Langfuse ו־LangSmith מכסות תפקיד חופף; OTel משלים את שלושתן. הוספת הרשומה מיועדת להשוואה, לא לחובת התקנה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('arize-phoenix',0,'תפקיד וזרימת עבודה','Phoenix משלבת OTLP/OpenInference, הערכות וניסויים. היא מובחנת מ־Arize AX; תג release של רכיב Phoenix MCP אינו גרסת שרת Phoenix.');
insert into academy.entry_sections (entry_id,position,title,body) values ('arize-phoenix',1,'מסלול לימוד ושילוב ב־C#/.NET','העשרה והשוואה: אין צורך ב־backend שלישי אחרי בחירת Langfuse או LangSmith. לקוחות Python/TypeScript; .NET דרך OTLP ו־manual spans. אין הבטחת auto-instrumentation או שוויון יכולות eval לכל שפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('arize-phoenix',2,'יתרונות ומתי לבחור','מחברת חקירת traces ל־datasets וניסויים באותו תהליך לימודי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('arize-phoenix',3,'חסרונות, אבטחה ורישוי','רישיון ELv2 כולל מגבלה על הצעת יכולות מהותיות כשירות מנוהל לצד שלישי; אין לתאר MIT/Apache או היתר גורף בגלל תווית source-available. עלות אירוח ושופטים אינה נעלמת בפריסה עצמית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('arize-phoenix',4,'השוואה לחלופות','Langfuse ו־LangSmith מכסות תפקיד חופף; OTel משלים את שלושתן. הוספת הרשומה מיועדת להשוואה, לא לחובת התקנה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('arize-phoenix','enrichment','העשרה להשוואת workflow של retrieval וניסויים ורישוי, תוך צמצום חפיפה למסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('arize-phoenix','פלטפורמה לניתוח traces, datasets וניסויי הערכה, כחלופת העשרה עם רישיון Elastic License2.0.','לקוחות Python/TypeScript; .NET דרך OTLP ו־manual spans. אין הבטחת auto-instrumentation או שוויון יכולות eval לכל שפה.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
