insert into academy.entry_categories (entry_id,category_id,position) values ('nemo-guardrails','10',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('nemo-guardrails','בדיקות תוכנה, לוגים והרשאות; קראו יסודות איכות ואבטחה לפני בחירת פלטפורמה.','דוגמה מעשית מוצעת שלא הורצה: הגדירו rail לתחום שיחה ולקלט לא תקין; הרשאת כתיבת SQL נשארת ב־.NET. בדקו false positives/negatives ו־fallback שאינו מבצע פעולה כשאין verdict ברור.','הכינו תוכנית בדיקה לתרחיש המתואר עם קלט תקין, קלט חסר, הרשאה חסרה וכשל תשתית. תעדו endpoint, גרסה ונתיב נתונים. השוו לחלופה אחת בלבד והפרידו תקינות תשובה מהרשאה לבצע פעולה.','ספריית Python ומסלול API server לשילוב .NET דרך HTTP. SDK C# מקומי לא אומת; זהו שירות נוסף עם אחריות תפעולית.','validation, least privilege ואישור משתמש הם נקודת ההתחלה. Promptfoo בוחנת כשל ו־Microsoft Evaluation מעריכה תוצאות; הן משלימות ולא אותה שכבת policy.');
insert into academy.entry_sections (entry_id,position,title,body) values ('nemo-guardrails',0,'תפקיד וזרימת עבודה','Rails מגדירות מדיניות התנהגות ובדיקות בזמן ריצה. classifier, flow או חסימת prompt אינם הוכחה שכל פעולה עסקית מורשית; הרשאות SQL/REST חייבות להיאכף בשירות העסקי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('nemo-guardrails',1,'מסלול לימוד ושילוב ב־C#/.NET','התמחות והעשרה כשנדרשת runtime policy; אבטחה בסיסית והרשאות מתחילות כבר בפרק היסודות. ספריית Python ומסלול API server לשילוב .NET דרך HTTP. SDK C# מקומי לא אומת; זהו שירות נוסף עם אחריות תפעולית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('nemo-guardrails',2,'יתרונות ומתי לבחור','מאפשרת ללמוד policy כשכבה מפורשת ולהפריד מדיניות שיחה מלוגיקת יישום.');
insert into academy.entry_sections (entry_id,position,title,body) values ('nemo-guardrails',3,'חסרונות, אבטחה ורישוי','תפעול Python ושופטים/מסננים מוסיפים latency ועלות שלא נמדדו. Apache2 של הספרייה אינו רישיון מודלים או שירותי NIM/NGC; אין הבטחת חסינות מ־prompt injection.');
insert into academy.entry_sections (entry_id,position,title,body) values ('nemo-guardrails',4,'השוואה לחלופות','validation, least privilege ואישור משתמש הם נקודת ההתחלה. Promptfoo בוחנת כשל ו־Microsoft Evaluation מעריכה תוצאות; הן משלימות ולא אותה שכבת policy.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('nemo-guardrails','enrichment','העשרה לשכבת policy ניתנת להגדרה, אחרי validation והרשאות רגילים; אין צורך בתרגול בכל פרויקט.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('nemo-guardrails','ערכת Python לבדיקות ולמדיניות קלט, פלט וזרימת שיחה בזמן ריצה; אינה תחליף להרשאות עסקיות.','ספריית Python ומסלול API server לשילוב .NET דרך HTTP. SDK C# מקומי לא אומת; זהו שירות נוסף עם אחריות תפעולית.','verified','מאגר ליבת הפרויקט בלבד; מדידת מחקר מתוארכת אינה מדד שימוש או איכות.','2026-11-03');
