insert into academy.entry_language_labels (entry_id,position,label) values ('mcp',0,'לא תלוי בשפה');
insert into academy.entry_language_labels (entry_id,position,label) values ('mcp',1,'C#/.NET — SDK רשמי');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp',5,'מפרט2026-07-28 וגבולות תאימות','במפרט זה בקשות יוזם הלקוח, וגרסה ויכולות נשלחות כ־metadata לכל בקשה. המודל discovery-first ו־stateless; initialize ו־session של גרסאות קודמות הם מסלולי תאימות ולא ברירת מחדל אוניברסלית. stdio מפעיל subprocess; Streamable HTTP משתמש ב־POST ומחזיר JSON או SSE בהקשר הבקשה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp',6,'אימות ושילוב ב־.NET','Authorization אופציונלי במפרט בכללותו; כאשר הוא נתמך ב־HTTP חל מסלול האימות המתועד, ואילו stdio משתמש ב־credentials סביבתיים ולא באותו OAuth flow. אין בכך היתר לחשוף שרת בלתי מוגן. אכפו scopes, audience והימנעות מ־token passthrough ובדקו SSRF. SDK אינו מעניק הרשאת SQL.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mcp',7,'יתרונות, חסרונות וחלופות','חוזה משותף מאפשר למחזר API עסקי ללקוחות תואמים; המחיר הוא ניהול גרסה, transport ואימות נוסף. רישוי המפרט וה־SDKs במעבר Apache2/MIT עם תיעוד CC-BY4 לפי הקבצים הרלוונטיים; אין להסיק רישיון כל שרת מהרישיון של הפרוטוקול. Registry עדיין Preview ומשמש גילוי metadata, לא אישור אבטחה או היתר להריץ בינארי.');
