insert into academy.entry_language_labels (entry_id,position,label) values ('langfuse',0,'Python');
insert into academy.entry_language_labels (entry_id,position,label) values ('langfuse',1,'JavaScript/TypeScript');
insert into academy.entry_language_labels (entry_id,position,label) values ('langfuse',2,'C#/.NET דרך OpenTelemetry');
insert into academy.entry_sections (entry_id,position,title,body) values ('langfuse',5,'תאימות SDK, שרת ו־.NET','Python SDKv5 ו־JS/TSv6 דורשים Langfusev4 מתאים; לשרתv3 יש להשתמש בגרסאות SDK הקודמות לפי המטריצה. .NET מייצאת traces דרך OTLP/HTTP עם headers/mapping/context המתועדים, לא SDK C# מלא ולא gRPC. יש לבדוק בנפרד prompts ו־evaluation API.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langfuse',6,'מועד מעבר מתוכנן ולא הפסקת מוצר','ל־Langfuse Cloud מתוכנן16/11/2026 סיום קליטת tracing ב־POST /api/public/ingestion, עם חריג scores. נכון לאימות03/11 זהו מועד עתידי; Langfuse אינה Legacy או Discontinued. self-host תלוי גרסה, ויש להעדיף מטריצת תאימות עדכנית על snippet ישן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langfuse',7,'יתרונות, חסרונות ורישוי','traces, prompts ו־datasets יכולים לקשר כשל יחיד להערכה חוזרת. מנגד, self-host מחייב תפעול ונפח אחסון; coreMIT אינו כולל כל יכולת Enterprise. server-side masking, retention policies, audit logs ו־project RBAC תלויים במהדורה; תכננו redaction ביישום לפני export.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langfuse',8,'מסלול מרכזי לעומת חלופות','רמת החובה נשמרת, אך אין חובה להשתמש דווקא במוצר זה. לומדים trace, dataset והפיכת failure ל־regression במערכת אחת; LangSmith ו־Phoenix הן חלופות להשוואה. אין צורך לתרגל כל backend או כל eval runner.');
