insert into academy.category_guides (category_id,title,introduction,note) values ('10','מאיכות והרשאות לבדיקות וחקירת ריצות','ליבה: dataset קטן ו־threat model → בדיקות .NET → OTel → backend אחד → regression. Langfuse נשארת בחשיבות חובה, אך אין חובה להשתמש דווקא בה: אפשר ללמוד במערכת חלופית. אין צורך לתרגל את כל הכלים שנוספו לקטלוג.','בחרו eval runner אחד ומערכת tracing אחת לתרגיל ראשון. Ragas להתמחות RAG; LangSmith/Phoenix להשוואה; NeMo העשרה ל־runtime policy. Preview/Experimental ונתיבי ענן נבדקים לפי רכיב, לא לפי שם מוצר. דוגמאות לא הורצו; eval pass אינו הוכחת בטיחות.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',0,'ai-quality-security-fundamentals','ליבה: dataset, נכונות, latency, עלות, redaction והרשאה הם ממדים נפרדים.','יסודות איכות ואבטחה');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',1,'microsoft-ai-evaluation','ליבה ל־C#: assertions רגילות ואז מעריך אחד עם כיול אנושי; Safety עשויה להשתמש בשירות Foundry ו־RTC Experimental.','בדיקות .NET');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',2,'opentelemetry','ליבה: ActivitySource לשרשרת REST/SQL/model ו־exporter אחד; בלי capture רגיש כברירת מחדל.','Instrumentation');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',3,'langfuse','ליבה: בחרו backend אחד והפכו trace של כשל ל־regression. LangSmith או Phoenix הן חלופות, ואין חובה להפעיל דווקא Langfuse.','חקירת ריצה');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',4,'promptfoo','ליבה לפי צורך CI: בדקו יעד HTTP מורשה; בחרו בו או ב־runner .NET ראשון, לא חובה לתרגל את שניהם.','בדיקות חיצוניות');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',5,'ragas','התמחות RAG: הפרידו retrieval ו־faithfulness רק כשתהליך Python מוסיף ערך.','הערכת RAG');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',6,'langsmith','השוואה: בחנו workflow ומהדורות מסחריות כחלופה ל־Langfuse, לא backend שני חובה.','חלופת תצפיתיות');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',7,'arize-phoenix','העשרה: השוו ניסויים ורישוי ELv2; אין צורך במערכת שלישית.','חלופת ניסויים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('10',8,'nemo-guardrails','התמחות: הוסיפו rails רק כשנדרשת runtime policy; ההרשאות נשארות בשירות העסקי.','מדיניות בזמן ריצה');
insert into academy.category_guides (category_id,title,introduction,note) values ('09','מחוזה כלי עסקי לאינטגרציה תואמת MCP','המסלול המרכזי למפתח .NET: יסודות חוזים והרשאות → MCP → SDK C# אחד → Inspector → אינטגרציה בקריאה בלבד. השוואה אינה חובת תרגול: בחרו כלי אחד בכל תפקיד ושמרו את הלוגיקה העסקית בשירות הקיים.','הסתעפויות: FastMCP לצוות Python; Playwright לצורך UI; Composio העשרה לחיבורים מנוהלים. Registry עדיין Preview, אינו אישור אמון. דוגמאות לא הורצו; תאימות גרסה והרשאות דורשות בדיקה לפני מעבדה.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',0,'tool-integration-fundamentals','ליבה: הבינו DTO/OpenAPI, הרשאה, idempotency ואישור פעולה לפני חיבור מודל לכלי.','חוזים והרשאות');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',1,'mcp','ליבה: הפרידו host/client/server, transports וגרסת מפרט; זהו היכן נשמרת זהות המשתמש.','הפרוטוקול');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',2,'mcp-csharp-sdk','ליבה: ממשו תכנון שרת .NET קטן לקריאה בלבד. SDK אחד מספיק; אין צורך לתרגל גם Python.','מסלול C#');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',3,'mcp-inspector','ליבה: בדקו discovery, קלט שגוי והרשאה חסרה בלי להסתמך על בחירת כלי של מודל.','בדיקת שרת');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',4,'github-mcp-server','ליבה מעשית: בחרו toolsets מצומצמים ו־read-only לתרחיש GitHub מורשה.','אינטגרציה ראשונה');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',5,'playwright-mcp','התמחות UI בלבד: כשאין API מתאים, השוו MCP לבדיקת Playwright דטרמיניסטית.','הסתעפות דפדפן');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',6,'fastmcp','השוואת Python: גשר OpenAPI אינו היתר לחשוף כל endpoint; דלגו אם מסלול .NET מספיק.','חלופת Python');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('09',7,'composio','העשרה: בחנו OAuth מנוהל ובידוד משתמשים רק כשמספר החיבורים מצדיק שירות נוסף.','חיבורים מנוהלים');
insert into academy.schema_migrations(version,description) values(13,'Approved T09/Q10: fifteen additions, two corrections and two learning guides; keep Langfuse must_learn');
