begin isolation level serializable;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 12 then raise exception 'Expected schema version 12'; end if;
 if (select count(*) from academy.entries)<>71 then raise exception 'Catalog changed since review'; end if;
 if exists(select 1 from academy.entries where id in ('tool-integration-fundamentals','mcp-csharp-sdk','mcp-inspector','fastmcp','github-mcp-server','playwright-mcp','composio','ai-quality-security-fundamentals','opentelemetry','microsoft-ai-evaluation','promptfoo','ragas','langsmith','arize-phoenix','nemo-guardrails') or slug in ('tool-integration-fundamentals','mcp-csharp-sdk','mcp-inspector','fastmcp','github-mcp-server','playwright-mcp','composio','ai-quality-security-fundamentals','opentelemetry','microsoft-ai-evaluation','promptfoo','ragas','langsmith','arize-phoenix','nemo-guardrails') or lower(name) in ('כלים ואינטגרציות — יסודות, חוזים והרשאות','mcp c# sdk','mcp inspector','fastmcp','github mcp server','playwright mcp','composio','איכות, תצפיתיות ואבטחת ai — יסודות','opentelemetry — .net & genai','microsoft.extensions.ai.evaluation','promptfoo','ragas','langsmith','arize phoenix','nvidia nemo guardrails')) then raise exception 'Candidate identity already exists'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/modelcontextprotocol/csharp-sdk','https://github.com/modelcontextprotocol/inspector','https://github.com/PrefectHQ/fastmcp','https://github.com/github/github-mcp-server','https://github.com/microsoft/playwright-mcp','https://github.com/ComposioHQ/composio','https://github.com/open-telemetry/opentelemetry-dotnet','https://github.com/promptfoo/promptfoo','https://github.com/vibrantlabsai/ragas','https://github.com/Arize-ai/phoenix','https://github.com/NVIDIA-NeMo/Guardrails')) then raise exception 'Candidate repository already represented'; end if;
 if exists(select 1 from academy.category_guides where category_id in ('09','10')) then raise exception 'Reviewed guide changed'; end if;
 if (select document from academy.entry_documents where slug='langfuse') is distinct from '{"id":"langfuse","kind":"platform","name":"Langfuse","slug":"langfuse","addedAt":"2026-10-31","example":"תרחיש לימודי: תשובה שגויה על נוהל רכש. ב־Trace בודקים האם אוחזר סעיף לא נכון או שהמודל התעלם מסעיף נכון, ואז בוחנים תיקון על כמה שאלות.","sources":[{"url":"https://langfuse.com/docs","title":"Langfuse — Overview","supports":"Traces, ניהול הנחיות, הערכה, SDKs ו־OpenTelemetry. תכנון שדות, פרטיות וסט הבדיקות הוא הצעה לימודית שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמה לתצפיתיות, ניהול הנחיות והערכה של יישומי AI.","exercise":"הגדר Trace לתרחיש בקשת ציוד עם שלושה שלבים. תוצר: רשימת שדות לתיעוד, שדות להשחרה וחמש דוגמאות להערכת גרסה חדשה.","revision":2,"sections":[{"text":"ביישום AI, תשובה לא טובה יכולה לנבוע מאחזור, מכלי, מהנחיה או מהמודל. Langfuse מרכזת Traces, ניהול הנחיות והערכה כדי לעזור לעקוב אחרי ההתנהגות והאיכות.","title":"איזו בעיה היא פותרת?"},{"text":"Trace מייצג פעולה כוללת, ובתוכו מתעדים קריאות מודל, אחזור ופעולות נוספות. אפשר לבחון זמן, עלות ותוצאות. השוואה בין גרסאות מחייבת לשמור גם איזה מודל והנחיה שימשו.","title":"מה מודדים?"},{"text":"כהקבלה לימודית, זה דומה למעקב בקשה שחוצה שירותים, אך מוסיף עניין באיכות התשובה ובהקשר. התיעוד מציין OpenTelemetry; יש לבדוק פרטי אינטגרציה לשפה לפני חיבור.","title":"החיבור ל־.NET"},{"text":"לוג עוזר להבין מה קרה במקרה אחד; הערכה שיטתית בודקת אם שינוי משפר תוצאות על סט דוגמאות. צריך להגדיר מה נכון, ולא להסתפק בציון נוסף שמודל נתן.","title":"לוגים מול Evals"},{"text":"המלצה: סנן מידע רגיש לפני התיעוד, קבע מדיניות שמירה ובדוק מי רואה קלט ופלט. עלות ניטור ואחסון יכולה לגדול עם נפח הפעילות גם אם המודל עצמו זול.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["10"],"addedAtBasis":"historical_backfill","relatedSlugs":["llamaindex","openai-agents-sdk","langgraph"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"לוגים, מזהי בקשות, מדידת זמן וסט בדיקות.","alternativesNote":"LangSmith ו־Phoenix הם מועמדים נוספים במפת הידע. אפשר להתחיל בלוגים מובנים ובבדיקות איכות קטנות, ולהוסיף פלטפורמה כשצריך חקירה והשוואה שיטתית.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"המקור מציין SDKs ב־Python/JavaScript ואינטגרציות OpenTelemetry. אין להסיק שכל שילוב .NET נתמך באותה רמת פירוט ללא בדיקה ייעודית."}'::jsonb then raise exception 'Reviewed document changed: langfuse'; end if;
 if (select document from academy.entry_documents where slug='mcp') is distinct from '{"id":"mcp","kind":"protocol","name":"MCP","slug":"mcp","addedAt":"2026-10-31","example":"דוגמה לימודית: שרת חושף פעולה לבדיקת מלאי. עוזר ארגוני קורא לה דרך לקוח MCP ומציג את התוצאה לעובד.","sources":[{"url":"https://modelcontextprotocol.io/docs/2026-07-28/learn/architecture","title":"תיעוד הארכיטקטורה הרשמי של MCP","supports":"הגדרת הפרוטוקול, מארח/לקוח/שרת, שכבות התקשורת והיכולות שהשרת חושף. הדוגמה והתרגיל נכתבו לצורכי לימוד.","checkedAt":"2026-10-31"}],"summary":"פרוטוקול לחילופי הקשר בין יישומי AI לבין שרתים המספקים מידע ופעולות.","exercise":"תכנן כלי בדיקת מלאי: שם, קלט, פלט ושגיאות. שרטט מארח, לקוח ושרת, וסמן היכן נבדקת זהות המשתמש. תוצר: חוזה כלי והסבר מדוע קוד פריט תקין אינו מהווה הרשאה לקריאה.","revision":2,"sections":[{"text":"מגדיר דרך משותפת לחשיפת כלים, מקורות מידע ותבניות הנחיה ליישומי AI.","title":"איזו בעיה הוא פותר?"},{"text":"יישום מארח מנהל לקוחות MCP. כל לקוח מתקשר עם שרת המספק יכולות. שכבת הנתונים מבוססת JSON-RPC; התקשורת יכולה להתבצע מקומית או מרחוק.","title":"איך זה עובד?"},{"text":"כהקבלה לימודית, שרת MCP הוא Adapter מעל יכולות עסקיות. הוא יכול לקרוא ל־API קיים במקום לשכפל את הלוגיקה שלו. היישום המארח מנהל לקוח לכל שרת שאליו הוא מתחבר.","title":"החיבור ל־REST ול־C#"},{"text":"המלצה: כשיכולת צריכה להיות נגישה ליישומי AI תואמים דרך חוזה משותף. אם יש לקוח אחד ו־API פשוט, בדוק גם חיבור ישיר לפני הוספת שכבה.","title":"מתי לבחור?"},{"text":"עצם חשיפת כלי אינה הרשאה לבצע אותו. שרת צריך לבדוק הרשאות ולתחום פעולות; קלט מהמודל וממקורות חיצוניים דורש ולידציה. כתיבה עסקית רגישה צריכה לעבור אישור ומניעת כפילות.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["09"],"addedAtBasis":"historical_backfill","relatedSlugs":["microsoft-agent-framework","openai-agents-sdk","n8n"],"revisionNote":"פרק יסודות מורחב. האימות מתייחס למבנה הפרוטוקול; שיקולי הרשאות, חלופות והתרגילים הם הסבר הנדסי שלנו. אין כאן מטריצת SDKs או הבטחת תאימות גרסאות.","prerequisites":"HTTP, JSON, חוזי API והרשאות.","alternativesNote":"אפשר לחשוף שירות REST ישירות או לממש Function Calling בספק מודל. MCP מוסיף חוזה חיבור משותף ליישומים תואמים; בחירה בו תלויה במי שיצרוך את הכלים.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"הפרוטוקול מפריד חוזה תקשורת ממימוש. לפני בחירת SDK ב־C#, Python או TypeScript יש לבדוק את התיעוד והגרסה הרלוונטיים; שלושת השמות אינם מבטיחים שוויון יכולות."}'::jsonb then raise exception 'Reviewed document changed: mcp'; end if;
end $$;
update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='מחקר09/10 מאושר עם הבחנת מסלול מרכזי וחלופות; נשמרה חשיבות חובה. פרקים ומקורות קודמים נשמרו; דוגמאות לא הורצו.' where slug='mcp';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: שרת get_stock מעל REST מחסן מאמת משתמש והרשאת מחסן לפני קריאת SQL. לקוח C# מגלה כלי וקורא לו; Inspector בודק את אותו חוזה ללא מודל.',exercise='שרטטו host/client/server והצמידו מפרט2026-07-28 או גרסת תאימות מפורשת. השוו stdio ל־HTTP וכתבו בדיקות הרשאה, audience וקלט חסר בלי לחשוף כלי כתיבה.',language_support_note='MCP הוא פרוטוקול בלתי תלוי בשפה; קיימים SDKs רשמיים ובהם C#, Python ו־TypeScript. יש להצמיד גרסת SDK ומפרט ואין להבטיח parity. SDK C# מקומי שונה מצריכת שרת Python דרך MCP.',alternatives_note='REST ישיר או tool calling בספק אחד עשויים להספיק. MCP נותן חוזה משותף; SDK C# הוא מימוש, Inspector בדיקה, ו־FastMCP חלופת Python. אין צורך לתרגל את כל המימושים.' where entry_id='mcp';
update academy.catalog_facts set language_support_summary='MCP הוא פרוטוקול בלתי תלוי בשפה; קיימים SDKs רשמיים ובהם C#, Python ו־TypeScript. יש להצמיד גרסת SDK ומפרט ואין להבטיח parity. SDK C# מקומי שונה מצריכת שרת Python דרך MCP.',reviewed_at='2026-11-03' where entry_id='mcp';
update academy.learning_guidance set reason='בסיס חובה לחיבור יישומי AI לכלים ולמקורות; אין חובה להשתמש בפרוטוקול כשהצרכן היחיד מסתפק ב־REST ישיר.',reviewed_at='2026-11-03' where entry_id='mcp';
delete from academy.entry_language_labels where entry_id='mcp';
update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='מחקר09/10 מאושר עם הבחנת מסלול מרכזי וחלופות; נשמרה חשיבות חובה. פרקים ומקורות קודמים נשמרו; דוגמאות לא הורצו.' where slug='langfuse';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: trace של בקשת רכש כולל אחזור נוהל, קריאת מודל והצעת כלי. השחירו מזהים לפני export מ־.NET דרך OTel/HTTP והפכו כשל אחד למקרה regression, בלי לתעד מפתחות או מסמכים מלאים.',exercise='תכננו dataset קטן ו־trace עם parent/child, בדיקת redaction ותאימות SDK/server. בחרו backend אחד בלבד; השוו על הנייר את החלופות לפי רישוי, פריסה ונתיב מידע.',language_support_note='SDKs רשמיים Pythonv5 ו־JS/TSv6 דורשים serverv4 מתאים (מינימום4.59.0 לפי מטריצת SDK). .NET דרך OpenTelemetry/OTLP HTTP ו־Public API; אין הבטחת SDK Langfuse C# מקומי או parity לניהול prompts/evals. יעד OTel המתועד אינו gRPC.',alternatives_note='LangSmith ו־Phoenix הן חלופות לחקירת ריצה וניסויים; אין חובה להשתמש דווקא ב־Langfuse או להתקין שלוש פלטפורמות. OTel משמש instrumentation, ו־Microsoft Evaluation/Ragas/Promptfoo משלימות בדיקות בשכבות שונות.' where entry_id='langfuse';
update academy.catalog_facts set language_support_summary='SDKs רשמיים Pythonv5 ו־JS/TSv6 דורשים serverv4 מתאים (מינימום4.59.0 לפי מטריצת SDK). .NET דרך OpenTelemetry/OTLP HTTP ו־Public API; אין הבטחת SDK Langfuse C# מקומי או parity לניהול prompts/evals. יעד OTel המתועד אינו gRPC.',reviewed_at='2026-11-03' where entry_id='langfuse';
update academy.learning_guidance set reason='נשאר חובה ללמוד לפי בחירת העריכה: היכרות מעשית עם tracing והערכה חשובה, אך אין חובה להשתמש דווקא ב־Langfuse. אפשר לבחור LangSmith או Phoenix ולהבין את אותם יסודות.',reviewed_at='2026-11-03' where entry_id='langfuse';
delete from academy.entry_language_labels where entry_id='langfuse';
do $$ begin
 if (select count(*) from academy.entries)<>86 or (select count(*) from academy.entries where publication_status='published')<>84 then raise exception 'Unexpected final counts'; end if;
 if (select count(*) from academy.entry_categories where category_id='09')<>8 or (select count(*) from academy.entry_categories where category_id='10')<>9 then raise exception 'Unexpected category counts'; end if;
 if exists(select 1 from academy.learning_guidance where entry_id in ('langfuse','mcp') and priority<>'must_learn') then raise exception 'Must-learn priorities must be preserved'; end if;
 if exists(select 1 from academy.entries where slug in ('langfuse','mcp') and revision<>3) then raise exception 'Missing corrections'; end if;
end $$;
commit;
